  2091          hrecs->pg[i].prev_id = hrecs->pg[kh_val(hrecs->pg_hash, k)].id;
  2092          hrecs->pg_end[kh_val(hrecs->pg_hash, k)] = -1;
  2093          chain_size[i] = chain_size[kh_val(hrecs->pg_hash, k)]+1;
  2094      }
  2095
  2096      for (i = j = 0; i < hrecs->npg; i++) {
  2097          if (hrecs->pg_end[i] != -1 && chain_size[i] > 0)
  2098              hrecs->pg_end[j++] = hrecs->pg_end[i];
  2099      }
  2100      /* Only leafs? Choose the last one! */
  2101      if (!j && hrecs->npg_end > 0) {
  2102          hrecs->pg_end[0] = hrecs->pg_end[hrecs->npg_end-1];
